def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_int(s: str) -> int:
        if len(s) <= 4000:
            return int(s)
        res = 0
        for i in range(0, len(s), 4000):
            chunk = s[i:i + 4000]
            res = res * (10 ** len(chunk)) + int(chunk)
        return res

    def ipow(a: int, b: int) -> int:
        if b < 0:
            raise ZeroDivisionError
        if b == 0 or a == 1:
            return 1
        if a == 0:
            return 0
        if a == -1:
            return -1 if (b & 1) else 1
        return a ** b

    def parse_primary() -> int:
        nonlocal pos
        if expr[pos] == '(':
            pos += 1
            val = parse_expr()
            pos += 1
            return val
        start = pos
        while pos < n and '0' <= expr[pos] <= '9':
            pos += 1
        return parse_int(expr[start:pos])

    def parse_unary() -> int:
        nonlocal pos
        chain: list[tuple[int, int]] = []
        while True:
            skip_spaces()
            neg = 0
            while pos < n and expr[pos] == '-':
                neg += 1
                pos += 1
                skip_spaces()
            val = parse_primary()
            chain.append((neg, val))
            skip_spaces()
            if pos < n and expr[pos] == '^':
                pos += 1
            else:
                break
        neg, res = chain.pop()
        if neg & 1:
            res = -res
        while chain:
            neg, base = chain.pop()
            res = ipow(base, res)
            if neg & 1:
                res = -res
        return res

    def parse_term() -> int:
        nonlocal pos
        left = parse_unary()
        while pos < n:
            op = expr[pos]
            if op == '*':
                pos += 1
                left *= parse_unary()
            elif op == '/':
                pos += 1
                right = parse_unary()
                if right == 0:
                    raise ZeroDivisionError
                q = abs(left) // abs(right)
                left = -q if (left < 0) ^ (right < 0) else q
            elif op == '%':
                pos += 1
                right = parse_unary()
                if right == 0:
                    raise ZeroDivisionError
                r = abs(left) % abs(right)
                left = -r if left < 0 else r
            else:
                break
        return left

    def parse_expr() -> int:
        nonlocal pos
        left = parse_term()
        while pos < n:
            op = expr[pos]
            if op == '+':
                pos += 1
                left += parse_term()
            elif op == '-':
                pos += 1
                left -= parse_term()
            else:
                break
        return left

    try:
        return parse_expr()
    except ZeroDivisionError:
        return "error"
